from .bts.bts_classical import BtsClassical
from .bts.bts_cloud_cu import BtsCloudCu
from .bts.bts_cloud_du import BtsCloudDu
from .bts.bts_enb import BtsEnb
from .exceptions import InvalidBtsType


class BtsFactory(object):
    """ Factory for BTS API """

    _bts_apis = {'ClassicalBts': BtsClassical,
                 'CloudBtsCu': BtsCloudCu,
                 'CloudBtsDu': BtsCloudDu,
                 'RealEnb': BtsEnb}

    @classmethod
    def get_bts(cls, bts_type, **kwargs):
        """
        Returns BTS API instance based on provided bts_type and additional arguments.
        :param bts_type: topology type of BTS to which requests for active alarms will be sent;
                         supported BTS types: 'ClassicalBts', 'CloudBts', 'RealEnb' (all of them are case-sensitive);
        :type bts_type: str
        :param kwargs: additional keyword arguments used when selecting proper BTS API;
                       when du_id provided then BtsCloudDu will be returned;
                       when cu_id provided without du_id then BtsCloudCu will be returned
        :return: appropriate BTS API instance
        :rtype: taf.ul.alarms_watchdog.bts.bts.Bts
        :raises InvalidBtsType: when unsupported bts_type provided
                                or bts_type is 'CloudBts' but no cu_id nor du_id was provided
        """
        bts_api = cls._get_bts_api(bts_type, **kwargs)
        return bts_api()

    @classmethod
    def _get_bts_api(cls, bts_type, **kwargs):
        if bts_type == 'CloudBts':
            bts_type = cls._detect_cloud_unit(**kwargs)

        bts_api = cls._bts_apis.get(bts_type, None)
        cls._check_bts_api(bts_api, bts_type)
        return bts_api

    @staticmethod
    def _detect_cloud_unit(**kwargs):
        if 'du_id' in kwargs:
            return 'CloudBtsDu'
        elif 'cu_id' in kwargs:
            return 'CloudBtsCu'
        else:
            raise InvalidBtsType('BTS type: CloudBts provided but without cu_id nor du_id specified.')

    @staticmethod
    def _check_bts_api(bts_api, bts_type):
        if bts_api is None:
            raise InvalidBtsType('Invalid BTS type provided: {}'.format(bts_type))
